      redirectAllowlist: (env.OAUTH_REDIRECT_ALLOWLIST ?? '').split(','), streamerId: env.TWITCH_STREAMER_ID, botId: env.TWITCH_BOT_ID,
      encryptionKey: env.TOKEN_ENCRYPTION_KEY, keeperIds, store, transport, production });
